b = randn(m,1);
epsilon = .1;

%% Solve in CVX
cvx_begin
  cvx_precision best
  variable X(n,n)
  minimize trace(X)
  subject to
    X == semidefinite(n)
    norm( A*vec(X) - b, Inf ) <= epsilon
cvx_end
X_CVX = X;
%% Solve in TFOCS
linear  = linop_compose( linop_matrix(A), linop_vec([n,n]) );
