for i = 1:N % For each discretization node we output the state.
    xj = x(:,i);
    rj = sx(:,1+(i-1)*(dN/dt):i*(dN/dt));
    for j = 1:dN/dt-1 % For each discretization node we propagate more accurately within, by using dt time-steps.
