    trace(C_p(:,:,n)*M(:,:,t))==P_inj(n,t);
    trace(C_q(:,:,n)*M(:,:,t))==Q_inj(n,t);

    %  and voltage constraints
    trace(C_v1(:,:,n)*M(:,:,t))<=V_max^2;
    trace(C_v1(:,:,n)*M(:,:,t))>=V_min^2;
end

end

