function [A, W, obj] = algo3(X, U, S, delta, Rprime, Ebs, Beta)

    n = size(X,1);
    m = size(X,2);
    A = zeros(n,n);
    W = ones(n,n);

    for t = 1:500
        cvx_begin
            variable eta(n,m)
            expression constr;
            for k = 1 : m
                constr = constr + eta(:,k)'*Rprime(:,:,k)*eta(:,k);
            end
            obj = 0;
            for i=1:n
